window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[324]={"id":"324","numero":324,"titre":"Éducation thérapeutique, observance et automédication","objectifs":[{"id":"324-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’éducation thérapeutique du patient et de ses principales étapes","contenu":"<p>L'<strong><span class=\"kw-def\">éducation thérapeutique du patient</span></strong> (ETP) est, selon l'<span class=\"kw-def\">OMS (1998)</span>, « un ensemble de pratiques visant à permettre au patient l'acquisition de <strong>compétences</strong>, afin de pouvoir prendre en charge de manière <strong>active</strong> sa maladie, ses soins et sa surveillance, <strong>en partenariat avec ses soignants</strong> ».</p>\n      <ul>\n        <li>Inscrite dans la <strong><span class=\"kw-def\">loi HPST</span></strong> et ses décrets d'application (qui précisent intervenants, déroulement et formation).</li>\n        <li>But : développer les <strong>connaissances et compétences</strong> du patient pour gagner en <span class=\"kw-def\">autonomie</span> et améliorer sa <span class=\"kw-def\">qualité de vie</span>.</li>\n        <li>Peut être proposée <strong>dès l'annonce du diagnostic</strong> d'une maladie chronique, ou à tout autre moment de son évolution.</li>\n        <li>Concerne <strong>tous les professionnels de santé</strong>.</li>\n      </ul>\n      <p>La démarche ETP se déroule en <strong>4 étapes</strong> :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Intitulé</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td><span class=\"kw-def\">Diagnostic éducatif</span></td><td>Identifier connaissances, besoins et attentes du patient ; formuler avec lui les compétences à acquérir</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td><span class=\"kw-def\">Programme personnalisé d'ETP</span></td><td>Définir les priorités d'apprentissage au regard du projet du patient</td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td><strong>Planification et mise en œuvre des séances</strong></td><td>Séances <span class=\"kw-clinique\">individuelles</span> et/ou <span class=\"kw-clinique\">collectives</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td><span class=\"kw-def\">Évaluation individuelle</span></td><td>Faire le point sur ce que le patient a compris et sait faire ; proposer un nouvel ETP selon les résultats</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> L'ETP transforme le patient en <strong>acteur</strong> de sa prise en charge — ce n'est ni de l'information ponctuelle, ni un simple conseil.</div>","frequence":0},{"id":"324-2","rang":"B","rubrique":"Définition","titre":"Connaître les principaux objectifs pédagogiques des programmes d’éducation thérapeutique du patient","contenu":"<p>L'objectif global d'un programme d'ETP est de permettre au patient atteint d'une <span class=\"kw-def\">maladie chronique</span> d'<strong>acquérir la capacité de gérer son traitement</strong>, de prévenir les complications de sa maladie et de conserver ou améliorer sa <span class=\"kw-def\">qualité de vie</span>.</p>\n      <p>Cet objectif se décline en <strong>3 familles de compétences à développer</strong> :</p>\n      <table >\n        <thead><tr><th>Compétence</th><th>Définition</th><th>Exemple</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Auto-soins</span></td><td>Décisions que le patient prend avec l'intention de modifier l'effet de la maladie sur sa santé</td><td>Adapter ses doses d'<span class=\"kw-ttt\">insuline</span></td></tr>\n          <tr><td><span class=\"kw-def\">Adaptation</span></td><td>Compétences personnelles, interpersonnelles, cognitives et physiques permettant de maîtriser et diriger son existence et de modifier son environnement</td><td>Vivre avec la maladie au quotidien</td></tr>\n          <tr><td><span class=\"kw-def\">Sécurité</span></td><td>Savoir dépister et prendre en charge des <span class=\"kw-alerte\">situations à risque</span></td><td><span class=\"kw-clinique\">Hypoglycémie</span> chez le diabétique ; <span class=\"kw-clinique\">fièvre</span> chez l'immunodéprimé</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Les <strong>compétences de sécurité</strong> sont celles qui évitent l'<span class=\"kw-alerte\">urgence</span> : le patient doit savoir reconnaître et gérer seul une situation menaçante.</div>","frequence":0},{"id":"324-3","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités d’évaluation de l’impact de l’éducation thérapeutique sur le succès du traitement","contenu":"<p>L'impact de l'ETP sur le succès du traitement s'évalue à <strong>5 niveaux</strong> complémentaires — du changement de comportement au bénéfice de vie :</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Ce qui est évalué</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Comportemental</span></td><td>Acquisition de <strong>compétences d'auto-soins</strong> et de <strong>sécurité</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Cognitif</span></td><td>Amélioration des <span class=\"kw-clinique\">croyances erronées</span>, des préjugés et des connaissances</td></tr>\n          <tr><td><span class=\"kw-def\">Médical</span></td><td>Amélioration des paramètres liés à la maladie : <span class=\"kw-bio\">HbA1c</span> (<span class=\"kw-def\">diabète</span>), exacerbations de <span class=\"kw-clinique\">BPCO</span>…</td></tr>\n          <tr><td><span class=\"kw-def\">Autonomie et sécurité</span></td><td>Réduction des <span class=\"kw-alerte\">effets indésirables</span>, des rechutes, des complications, des recours aux <span class=\"kw-alerte\">urgences</span> et hospitalisations</td></tr>\n          <tr><td><span class=\"kw-def\">Global</span></td><td>Amélioration de la <span class=\"kw-def\">qualité de vie</span> et réalisation des projets de vie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> L'évaluation ne se limite pas au <span class=\"kw-bio\">paramètre biologique</span> : un programme d'ETP « réussi » se juge aussi sur le comportement, les connaissances et la qualité de vie.</div>","frequence":0},{"id":"324-4","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de planification d’un projet pédagogique individualisé pour un porteur de maladie chronique (voir item 1)","contenu":"<p>Le <strong><span class=\"kw-def\">projet pédagogique individualisé</span></strong> (PPI) est l'ensemble des étapes permettant de mettre en place une approche thérapeutique <strong>adaptée à un patient</strong>, en favorisant son <span class=\"kw-def\">autonomie</span>, ses capacités de décision et ses compétences d'<span class=\"kw-def\">auto-soins</span>. Il est <strong>indiqué chez tout patient atteint d'une maladie chronique</strong>.</p>\n      <p>La <strong>loi HPST</strong> distingue <strong>3 types de programmes</strong> :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Description</th><th>Exemple</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Programme d'ETP</span></td><td>Proposable dans <strong>toutes</strong> les maladies chroniques</td><td><span class=\"kw-def\">Diabète</span>, <span class=\"kw-def\">asthme</span>, VIH…</td></tr>\n          <tr><td><span class=\"kw-def\">Actions d'accompagnement</span></td><td><strong>Assistance et soutien</strong> aux malades ou à leur entourage</td><td>Maladie d'Alzheimer</td></tr>\n          <tr><td><span class=\"kw-def\">Programmes d'apprentissage</span></td><td><strong>Gestes techniques</strong> pour l'utilisation d'un médicament ou d'une technique</td><td>Pompe à <span class=\"kw-ttt\">insuline</span> ; dispositifs inhalés dans l'<span class=\"kw-def\">asthme</span></td></tr>\n        </tbody>\n      </table>\n      <p>La <strong>planification</strong> suit les 4 étapes de la démarche ETP — diagnostic éducatif, programme personnalisé, séances, évaluation. Les <strong>séances</strong> obéissent à des modalités précises :</p>\n      <ul>\n        <li>Séances <strong>individuelles</strong> : <span class=\"kw-chiffre\">30 à 45 minutes</span>.</li>\n        <li>Séances <strong>collectives</strong> : <span class=\"kw-chiffre\">45 minutes</span> chez l'adulte (plus courtes chez l'enfant), regroupant <span class=\"kw-chiffre\">≥ 3 personnes</span> — maximum <span class=\"kw-chiffre\">6 à 8 enfants</span> ou <span class=\"kw-chiffre\">8 à 10 adultes</span> — pour favoriser le partage d'expérience.</li>\n      </ul>\n      <p>Le <span class=\"kw-def\">diagnostic éducatif</span>, première étape, explore le patient à travers <strong>5 questions</strong> :</p>\n      <table >\n        <thead><tr><th>Question</th><th>Dimension explorée</th></tr></thead>\n        <tbody>\n          <tr><td>« Qu'est-ce qu'il a ? »</td><td>Maladie, sévérité, comorbidités</td></tr>\n          <tr><td>« Qu'est-ce qu'il fait ? »</td><td>Dimensions sociale et professionnelle</td></tr>\n          <tr><td>« Qu'est-il ? »</td><td>Dimension psycho-affective, acceptation de la maladie</td></tr>\n          <tr><td>« Qu'est-ce qu'il sait ? »</td><td><span class=\"kw-clinique\">Croyances</span> et représentations</td></tr>\n          <tr><td>« Quels sont ses projets ? »</td><td>Attentes et besoins</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> Le PPI repose sur une démarche <strong>individualisée et participative</strong> : le programme se construit <strong>avec</strong> le patient, pas pour lui.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 1 — Relation médecin-malade</em></p>","frequence":0},{"id":"324-5","rang":"B","rubrique":"Prise en charge","titre":"Argumenter une prescription et l’éducation associée, expliquer les facteurs d’observance","contenu":"<p>L'<strong>interrogatoire</strong> et l'<strong>examen minutieux</strong> sont indispensables pour instaurer et suivre un traitement. La prescription tient compte de plusieurs <strong>déterminants</strong> :</p>\n      <table >\n        <thead><tr><th>Déterminant</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antécédents</strong></td><td>Médicaux, personnels et parentaux (maladie hépatique, rénale, neurologique, psychique)</td></tr>\n          <tr><td><strong>Allergie / iatrogénie</strong></td><td>Allergie, effets indésirables ou toxicité médicamenteuse antérieurs</td></tr>\n          <tr><td><strong>Médicaments en cours</strong></td><td>Ordonnances des autres médecins ; détection de l'<span class=\"kw-def\">automédication</span> → prévention du risque d'<span class=\"kw-alerte\">interaction</span></td></tr>\n          <tr><td><strong>Terrain</strong></td><td>Génétique ; âge physiologique ; <span class=\"kw-alerte\">grossesse</span> (risque tératogène / toxique), allaitement ; immunodépression</td></tr>\n          <tr><td><strong>Adaptation des posologies</strong></td><td>Poids / taille ; fonction rénale et hépatique ; <span class=\"kw-clinique\">déshydratation</span>, dénutrition. Vigilance accrue pour les <span class=\"kw-alerte\">médicaments à marge thérapeutique étroite</span> (<span class=\"kw-ttt\">digitaliques</span>, <span class=\"kw-ttt\">neuroleptiques</span>)</td></tr>\n          <tr><td><strong>Capacité du patient</strong></td><td>Compréhension des objectifs, lecture de l'ordonnance, repérage des EI ; altération cognitive, mnésique ou sensorielle</td></tr>\n          <tr><td><strong>Contexte et motivation</strong></td><td>Contexte socio-économique ; motivation à suivre le traitement malgré les contraintes</td></tr>\n        </tbody>\n      </table>\n      <p>L'<strong>éducation associée à la prescription</strong> est systématique : informer des objectifs et modalités du traitement, expliciter les <span class=\"kw-alerte\">effets indésirables</span> les plus fréquents ou graves, accompagner le patient pour favoriser l'<span class=\"kw-def\">observance</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ne jamais clore une consultation sans avoir <strong>commenté l'ordonnance</strong> (<span class=\"kw-chiffre\">posologie</span>, horaires des prises) et <strong>vérifié que les explications ont été comprises</strong> — c'est le premier levier d'observance.</div>","frequence":0},{"id":"324-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition des notions d’observance, de concordance et d’alliance en thérapeutique","contenu":"<p>Ces quatre notions décrivent, par degrés croissants de partenariat, la <strong>relation du patient à son traitement</strong> :</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Observance</span></td><td>Niveau auquel le comportement du patient <strong>coïncide</strong> avec les prescriptions médicamenteuses et les soins au sens large (consultations, explorations, surveillance) — <strong>donnée factuelle</strong>. Repose sur 2 éléments : <strong>adhésion</strong> et <strong>maintenance</strong> au traitement</td></tr>\n          <tr><td><span class=\"kw-def\">Adhésion</span></td><td><strong>Participation active</strong> du patient à sa prise en charge</td></tr>\n          <tr><td><span class=\"kw-def\">Concordance</span></td><td>Niveau d'<strong>accord</strong> entre les prescriptions médicales et le comportement du patient en réponse à ces recommandations</td></tr>\n          <tr><td><span class=\"kw-def\">Alliance thérapeutique</span></td><td><strong>Collaboration</strong> entre patient et soignant menant à des <strong>prescriptions concertées</strong> (inclut l'adhésion au traitement)</td></tr>\n        </tbody>\n      </table>\n      <p>L'observance couvre 3 champs : la <strong>prise médicamenteuse</strong> (posologie, horaires, nombre de prises), le <strong>suivi des règles hygiéno-diététiques</strong> et le <strong>suivi médical</strong> (venue aux visites de contrôle).</p>\n      <div class=\"callout callout-info\"><strong>Discriminant.</strong> L'<strong>observance</strong> est une mesure <strong>factuelle</strong> (le patient prend-il son traitement ?) ; l'<strong>alliance thérapeutique</strong> est une <strong>relation</strong> qui aboutit à des décisions partagées.</div>","frequence":0},{"id":"324-7","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les principaux éléments épidémiologiques de la non observance et ses conséquences potentielles en termes de santé publique","contenu":"<p>La <span class=\"kw-def\">non-observance</span> touche <strong>toutes les pathologies chroniques</strong> et constitue un problème majeur de santé publique :</p>\n      <ul>\n        <li>Concerne <span class=\"kw-chiffre\">20 à 70 %</span> des patients, en moyenne <span class=\"kw-chiffre\">~50 %</span> dans les maladies chroniques.</li>\n        <li>D'autant plus fréquente que la maladie est <strong>peu ou pas symptomatique</strong>.</li>\n        <li>Arrêt fréquent du traitement au bout de <span class=\"kw-chiffre\">2 ans</span> en <span class=\"kw-def\">prévention primaire</span> ; <span class=\"kw-chiffre\">~40 %</span> de non-observance chez les adolescents.</li>\n        <li><strong>Seuil</strong> définissant la mauvaise adhésion : <span class=\"kw-chiffre\">80 %</span> des prises.</li>\n      </ul>\n      <p>Elle expose à <strong>2 conséquences</strong> : l'<span class=\"kw-alerte\">échec thérapeutique</span> et les <span class=\"kw-alerte\">risques thérapeutiques</span>. À l'échelle de la santé publique, elle explique une partie de la <strong>différence entre les conclusions des essais cliniques et les résultats observés en pratique réelle</strong>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Devant tout <span class=\"kw-alerte\">échec</span> ou <span class=\"kw-alerte\">échappement thérapeutique</span>, <strong>toujours évoquer une non-observance avant d'ajouter un autre traitement</strong> — sinon, escalade thérapeutique injustifiée.</div>","frequence":0},{"id":"324-8","rang":"B","rubrique":"Définition","titre":"Savoir reconnaître les déterminants et les conséquences de la « malobservance »","contenu":"<p>La <span class=\"kw-def\">malobservance</span> se reconnaît par ses <strong>déterminants</strong> (les facteurs qui la favorisent) et par ses <strong>conséquences</strong>.</p>\n      <p><strong>Déterminants</strong> — les grands axes (détaillés dans l'objectif « facteurs liés à la non-observance ») :</p>\n      <ul>\n        <li>Liés à la <strong>maladie</strong> : affection <span class=\"kw-alerte\">peu symptomatique</span>, chronique.</li>\n        <li>Liés au <strong>traitement</strong> : stratégie complexe, <span class=\"kw-alerte\">mauvaise tolérance</span>.</li>\n        <li>Liés au <strong>patient</strong> : faible motivation, <span class=\"kw-clinique\">stress</span>, <span class=\"kw-clinique\">anxiété</span>, <span class=\"kw-clinique\">dépression</span>, non-compréhension des objectifs.</li>\n        <li>Liés au <strong>système de soins</strong> : faible implication des soignants, absence de prise en charge financière.</li>\n      </ul>\n      <p><strong>Conséquences</strong> de la malobservance :</p>\n      <table >\n        <thead><tr><th>Conséquence</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Échec thérapeutique</span></td><td>Maladie non contrôlée malgré une prescription adaptée</td></tr>\n          <tr><td><span class=\"kw-alerte\">Risque thérapeutique</span></td><td>Prises irrégulières, sur- ou sous-dosage, sevrage non maîtrisé</td></tr>\n          <tr><td><span class=\"kw-alerte\">Escalade thérapeutique injustifiée</span></td><td>Ajout de traitements alors que le vrai problème est l'observance</td></tr>\n          <tr><td><strong>Surcoût et iatrogénie</strong></td><td>Examens et traitements supplémentaires, hospitalisations évitables</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> Reconnaître une malobservance, c'est lire <strong>en miroir</strong> : ses déterminants orientent la prévention, ses conséquences alertent sur un échec qui n'est pas forcément un défaut du traitement.</div>","frequence":0},{"id":"324-9","rang":"B","rubrique":"Etiologie","titre":"Connaître les facteurs liés à la non-observance thérapeutique à prendre en compte dès l’initiation d’une prescription","contenu":"<p>Dès l'<strong>initiation d'une prescription</strong>, le médecin doit anticiper les facteurs qui favorisent — ou au contraire protègent de — la non-observance :</p>\n      <table >\n        <thead><tr><th>Facteurs d'observance</th><th>Facteurs de non-observance</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Traitement :</strong> administration simple ; courte durée ; bien toléré ; efficace<br>\n              <strong>Maladie :</strong> bon contrôle de la maladie sous-jacente<br>\n              <strong>Patient :</strong> a compris les bénéfices attendus, les modalités de prise, les risques d'EI et la surveillance ; absence de problématique psycho-sociale\n            </td>\n            <td>\n              <strong>Maladie :</strong> nature de l'affection, d'autant plus si <span class=\"kw-alerte\">non symptomatique</span> (<span class=\"kw-chiffre\">&gt; 60 %</span> de non-observance pour une simple anomalie biologique comme l'<span class=\"kw-bio\">hypercholestérolémie</span>)<br>\n              <strong>Traitement :</strong> <span class=\"kw-alerte\">complexité</span> de la stratégie ; mauvaise tolérance<br>\n              <strong>Patient :</strong> problèmes physiologiques ; faible motivation ; <span class=\"kw-clinique\">stress</span>, <span class=\"kw-clinique\">anxiété</span>, <span class=\"kw-clinique\">dépression</span> ; non-compréhension des objectifs<br>\n              <strong>Système :</strong> faible implication des soignants ; absence de prise en charge par les assurances\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le facteur le plus traître est la <strong>maladie peu symptomatique</strong> : sans gêne ressentie, le patient ne perçoit pas le bénéfice du traitement.</div>","frequence":0},{"id":"324-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les facteurs améliorant l’observance médicamenteuse et non médicamenteuse","contenu":"<p>Améliorer l'observance, c'est activer en miroir les <strong>facteurs d'observance</strong> — autant de <strong>leviers d'action</strong> médicamenteux et non médicamenteux :</p>\n      <table >\n        <thead><tr><th>Levier</th><th>Action concrète</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Simplifier le schéma</strong></td><td>Administration simple, nombre de prises réduit, traitement de courte durée quand c'est possible</td></tr>\n          <tr><td><strong>Optimiser le traitement</strong></td><td>Choisir un traitement <span class=\"kw-ttt\">bien toléré</span> et efficace ; obtenir un bon contrôle de la maladie</td></tr>\n          <tr><td><strong>Informer et éduquer</strong></td><td>Faire comprendre bénéfices attendus, modalités de prise, risques d'EI et surveillance — lien direct avec l'<span class=\"kw-def\">ETP</span></td></tr>\n          <tr><td><strong>Accompagner le patient</strong></td><td>Repérer et prendre en charge les problématiques <span class=\"kw-clinique\">psycho-sociales</span></td></tr>\n          <tr><td><strong>Renforcer la relation</strong></td><td><span class=\"kw-def\">Alliance thérapeutique</span>, <span class=\"kw-def\">décision partagée</span>, attitude de <span class=\"kw-def\">non-jugement</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> L'observance n'est pas qu'une affaire de médicament : la <strong>qualité de la relation</strong> et la <strong>compréhension du patient</strong> pèsent autant que le choix de la molécule.</div>","frequence":1},{"id":"324-11","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir qu’un même patient peut présenter différents comportements de non observance","contenu":"<p>La non-observance n'est <strong>pas un comportement unique</strong> : un même patient peut en cumuler plusieurs formes, et celles-ci varient dans le temps.</p>\n      <table >\n        <thead><tr><th>Comportement</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Non-retrait</strong></td><td>Le médicament n'est pas retiré en pharmacie</td></tr>\n          <tr><td><strong>Non-consommation</strong></td><td>Le médicament est acheté mais non consommé</td></tr>\n          <tr><td><strong>Sous-dosage</strong></td><td>Prises de doses <strong>plus faibles</strong> que prescrites (rarement plus fortes)</td></tr>\n          <tr><td><strong>Irrégularité</strong></td><td>Non-respect des horaires ou du nombre de prises</td></tr>\n          <tr><td><strong>Arrêt prématuré</strong></td><td>Non-respect de la <strong>durée</strong> du traitement</td></tr>\n          <tr><td><strong>Prise injustifiée</strong></td><td>Prises non prescrites, ± <span class=\"kw-def\">automédication</span> associée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La non-observance n'est pas un « <strong>tout ou rien</strong> » : elle est le plus souvent <strong>partielle</strong> et <strong>variable dans le temps</strong>. L'évaluer impose une exploration nuancée et répétée.</div>","frequence":0},{"id":"324-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la notion de non jugement","contenu":"<p>Le <strong><span class=\"kw-def\">non-jugement</span></strong> est une posture clé de l'évaluation de l'observance : aborder la question des prises <strong>sans connotation négative</strong>, sans culpabiliser ni réprimander le patient.</p>\n      <ul>\n        <li>Objectif : instaurer un <strong>climat de confiance</strong> qui permet au patient de <strong>déclarer honnêtement</strong> ses écarts de prise.</li>\n        <li>Conséquence directe : un recueil de l'observance <strong>plus fiable</strong> et donc une prise en charge mieux adaptée.</li>\n        <li>S'inscrit dans l'<span class=\"kw-def\">alliance thérapeutique</span> : le patient est un <strong>partenaire</strong>, pas un « mauvais élève ».</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> Un patient jugé se tait ou ment ; un patient écouté sans jugement <strong>dit la vérité</strong> sur sa prise — c'est la condition d'une évaluation utile.</div>","frequence":0},{"id":"324-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les techniques de communication pour évaluer au mieux l’observance médicamenteuse d’un patient","contenu":"<p>Évaluer l'observance combine un <strong>entretien adapté</strong> et des <strong>méthodes objectives</strong>. Aucune n'est parfaite : elles se complètent.</p>\n      <table >\n        <thead><tr><th>Méthode</th><th>Principe / limite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Interrogatoire du patient</strong></td><td>Poser <strong>directement</strong> la question, <strong>sans connotation négative</strong> (non-jugement)</td></tr>\n          <tr><td><strong>Boîtes retirées en pharmacie</strong></td><td>Reflète la <strong>délivrance</strong>, pas obligatoirement la prise réelle</td></tr>\n          <tr><td><span class=\"kw-bio\">Marqueurs biologiques de suivi</span></td><td><span class=\"kw-bio\">INR</span> sous anti-vitamine K ; <span class=\"kw-bio\">HbA1c</span> ; <span class=\"kw-bio\">LDL-cholestérol</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Dosages sanguins / urinaires</span></td><td>Dosage du médicament, prélevé de façon <strong>non programmée</strong> en consultation</td></tr>\n          <tr><td><strong>Efficacité du traitement</strong></td><td>Un échec doit faire évoquer la non-observance avant toute escalade</td></tr>\n          <tr><td><strong>Effets latéraux quasi constants</strong></td><td><span class=\"kw-bio\">Éosinopénie</span> sous <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-bio\">hyperuricémie</span> sous <span class=\"kw-ttt\">pyrazinamide</span> ; coloration orange des sécrétions sous <span class=\"kw-ttt\">rifampicine</span> ; <span class=\"kw-clinique\">bradycardie</span> sous <span class=\"kw-ttt\">bêta-bloquants</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Prendre un traitement chronique impose un <strong>changement de comportement en 5 stades</strong> — <span class=\"kw-def\">pré-intention</span>, <span class=\"kw-def\">intention</span>, <span class=\"kw-def\">préparation</span>, <span class=\"kw-def\">action</span>, <span class=\"kw-def\">maintien</span> — qu'il faut savoir situer pour adapter son discours.</div>","frequence":0},{"id":"324-14","rang":"A","rubrique":"Définition","titre":"Connaître la définition des différents types d’automédication","contenu":"<p>L'<strong><span class=\"kw-def\">automédication</span></strong> est l'utilisation, <strong>hors prescription médicale</strong>, par des personnes pour elles-mêmes ou leurs proches et <strong>de leur propre initiative</strong>, de médicaments considérés comme tels et ayant reçu une <span class=\"kw-def\">AMM</span>, avec possibilité d'assistance et de conseil du pharmacien (définition 2001 ; <span class=\"kw-def\">OMS 2000</span> : traitement de certaines maladies par les patients grâce à des médicaments autorisés, accessibles sans ordonnance, sûrs et efficaces).</p>\n      <p>On distingue <strong>2 situations d'automédication</strong> :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Automédication « sauvage »</span></td><td>Devant une situation aiguë qu'il connaît ou pense reconnaître, le patient prend un médicament — souvent dans la <strong>pharmacie familiale</strong> — de sa propre initiative ou sur conseil d'un proche</td></tr>\n          <tr><td><span class=\"kw-def\">Automédication contrôlée</span></td><td>Utilisation de médicaments dûment autorisés (médicament d'automédication) avec le <strong>conseil du pharmacien d'officine</strong> — AMM spécifique délivrée par une commission ad hoc de l'<span class=\"kw-def\">ANSM</span></td></tr>\n        </tbody>\n      </table>\n      <p>Selon ses modalités, l'automédication est dite <strong>responsable</strong> ou <strong>non responsable</strong> :</p>\n      <table >\n        <thead><tr><th>Automédication responsable</th><th>Automédication non responsable</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Symptômes courants et bénins ; courte durée ; spécialités <strong>simples</strong> (un seul principe actif) ; respect des exigences de sécurité ; consultation médicale si persistance ; information du médecin ; conseil du pharmacien ; éducation du patient</td>\n            <td>Réutilisation de médicaments <strong>antérieurement prescrits</strong> (armoire à pharmacie familiale) ; longue durée ; non déclarée au médecin / pharmacien ; inadaptée ; médicaments <span class=\"kw-alerte\">inconnus</span> (entourage, achat sur Internet) ; plusieurs médicaments ; pendant la <span class=\"kw-alerte\">grossesse</span> ou chez l'<span class=\"kw-alerte\">enfant en bas âge</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Discriminant.</strong> L'automédication <strong>contrôlée</strong> passe par un médicament autorisé et le conseil du pharmacien ; l'automédication <strong>« sauvage »</strong> repose sur l'initiative seule du patient, souvent avec un médicament déjà au domicile.</div>","frequence":1},{"id":"324-15","rang":"B","rubrique":"Epidémiologie","titre":"Savoir que l’automédication concerne la majorité des patients et doit être enseignée par le médecin","contenu":"<p>L'automédication est un phénomène <strong>répandu et sous-estimé</strong>, moins développé en France que chez ses voisins européens, mais qui concerne tout de même la <strong>majorité des patients</strong> (chiffres France, 2017) :</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>Recours à l'automédication</td><td><span class=\"kw-chiffre\">8 Français sur 10</span></td></tr>\n          <tr><td>Achat d'au moins 1 médicament sans ordonnance</td><td><span class=\"kw-chiffre\">20 %</span> des individus</td></tr>\n          <tr><td>Part du marché pharmaceutique global</td><td><span class=\"kw-chiffre\">10,8 %</span></td></tr>\n          <tr><td>Chiffre d'affaires</td><td><span class=\"kw-chiffre\">2,2 milliards €</span> (<span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">36 milliards €</span> pour les médicaments remboursables)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Profil</strong> des personnes qui se soignent par automédication : <span class=\"kw-etio\">femmes</span> (notamment pour soigner nourrissons et jeunes enfants) ; <span class=\"kw-etio\">âges actifs</span> (maximum vers <span class=\"kw-chiffre\">40-50 ans</span>, recours décroissant avec l'âge) ; <span class=\"kw-etio\">niveau social élevé</span>.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> L'automédication concernant la majorité des patients, elle <strong>doit être enseignée et encadrée par le médecin</strong> — donc <strong>recherchée systématiquement à l'interrogatoire</strong>, jamais ignorée ni simplement <span class=\"kw-ci\">interdite</span>.</div>","frequence":0},{"id":"324-16","rang":"A","rubrique":"Définition","titre":"Connaître les principaux médicaments concernés par l’automédication","contenu":"<p>Les médicaments d'automédication sont des médicaments <strong>sans ordonnance</strong>, répartis en <strong>2 grandes catégories</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Médicaments de « médication officinale »</span></td><td>Délivrés sur <strong>demande au pharmacien</strong> ; représentent la <strong>plupart</strong> des médicaments d'automédication ; remboursables <strong>ou non</strong> par la Sécurité sociale</td></tr>\n          <tr><td><span class=\"kw-def\">Médicaments en accès direct</span> (« libre accès », OTC)</td><td>Environ <span class=\"kw-chiffre\">600 médicaments</span> placés <strong>devant le comptoir</strong> (le patient se sert seul) ; <span class=\"kw-alerte\">non remboursables</span> ; liste fixée par l'<span class=\"kw-def\">ANSM</span>. 3 sous-catégories : <span class=\"kw-chiffre\">allopathiques</span>, <span class=\"kw-chiffre\">homéopathiques</span>, à base de <span class=\"kw-chiffre\">plantes</span></td></tr>\n        </tbody>\n      </table>\n      <p>Pour être éligible à l'automédication, un médicament doit remplir les <strong>conditions fixées par l'ANSM</strong> : rapport bénéfice/risque éminemment favorable ; pathologie ciblée <strong>courante et bénigne</strong> ; conditionnement, posologie et notice adaptés (courte durée) ; patient averti de la nécessité de consulter en cas de persistance des symptômes.</p>\n      <p><strong>Médicaments non éligibles</strong> : ceux comportant des <span class=\"kw-ci\">contre-indications majeures</span> ou des risques d'<span class=\"kw-alerte\">interactions</span> ; les médicaments destinés à la <span class=\"kw-alerte\">population pédiatrique</span>.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Depuis le <span class=\"kw-chiffre\">15 janvier 2020</span>, les médicaments contenant du <span class=\"kw-ttt\">paracétamol</span> et certains <span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ttt\">ibuprofène</span>, <span class=\"kw-ttt\">aspirine</span>) sont placés <strong>derrière le comptoir</strong> du pharmacien : toujours sans ordonnance, mais <strong>plus en accès direct</strong>.</div>","frequence":0},{"id":"324-17","rang":"B","rubrique":"Définition","titre":"Connaître les spécificités des médicaments de « médication officinale »","contenu":"<p>Les <strong><span class=\"kw-def\">médicaments de médication officinale</span></strong> sont aussi appelés « médicaments disponibles sans ordonnance ». Leurs spécificités :</p>\n      <ul>\n        <li>Délivrés sur <strong>demande au pharmacien</strong> — donc <strong>pas en libre accès</strong> devant le comptoir.</li>\n        <li>Représentent la <strong>plupart</strong> des médicaments d'automédication.</li>\n        <li>Peuvent être <strong>remboursables ou non</strong> par la Sécurité sociale.</li>\n        <li>Disposent d'une <span class=\"kw-def\">AMM</span> et peuvent aussi être <strong>prescrits par le médecin</strong>.</li>\n      </ul>\n      <p>Comparaison avec les médicaments en <strong>accès direct</strong> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Médication officinale</th><th>Accès direct (OTC)</th></tr></thead>\n        <tbody>\n          <tr><td>Positionnement</td><td>Derrière le comptoir, sur demande au pharmacien</td><td>Devant le comptoir, le patient se sert</td></tr>\n          <tr><td>Remboursement</td><td>Possible (remboursable ou non)</td><td><span class=\"kw-alerte\">Non remboursable</span></td></tr>\n          <tr><td>Intervention du pharmacien</td><td><strong>Systématique</strong> au moment de la demande</td><td>Conseil possible mais non systématique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Discriminant.</strong> Le critère qui sépare les deux catégories est le <strong>contact obligatoire avec le pharmacien</strong> : systématique pour la médication officinale, facultatif pour l'accès direct.</div>","frequence":0},{"id":"324-18","rang":"A","rubrique":"Etiologie","titre":"Connaître les acteurs de l’automédication et les facteurs influençant leurs choix","contenu":"<p>L'automédication met en jeu <strong>3 acteurs</strong> : le <strong>patient</strong> (et son entourage), le <strong>pharmacien d'officine</strong> et le <strong>médecin</strong>. Chacun a un rôle :</p>\n      <table >\n        <thead><tr><th>Acteur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Médecin</strong></td><td>Identifier l'automédication par un interrogatoire systématique ; connaître et dépister les <span class=\"kw-alerte\">interactions</span> ; rechercher une étiologie <span class=\"kw-alerte\">iatrogène</span> devant tout nouveau symptôme ; informer et éduquer ; déclarer tout EI grave ou inattendu au <span class=\"kw-def\">Centre Régional de Pharmacovigilance</span></td></tr>\n          <tr><td><strong>Pharmacien d'officine</strong></td><td>Conseil et information claire et adaptée ; explication des posologies et modalités ; consignes de vigilance (enfants, sujets âgés) ; recherche systématique d'une <span class=\"kw-alerte\">grossesse</span> ; recherche des <span class=\"kw-ci\">contre-indications</span> et précautions d'emploi</td></tr>\n          <tr><td><strong>Patient</strong></td><td>Initie la démarche, pour lui-même ou ses proches ; influencé par son entourage</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs influençant le choix</strong> de recourir à l'automédication : profil socio-démographique (<span class=\"kw-etio\">femmes</span>, <span class=\"kw-etio\">âges actifs</span>, <span class=\"kw-etio\">niveau social élevé</span>) ; <span class=\"kw-etio\">conseil de l'entourage</span> ; <span class=\"kw-etio\">accès facilité</span> (libre accès en officine, achat sur Internet) ; situation aiguë connue ou pensée reconnue ; contenu de la <span class=\"kw-etio\">pharmacie familiale</span>.</p>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> Médecin et pharmacien sont les deux <strong>garde-fous</strong> de l'automédication : le premier la dépiste à l'interrogatoire, le second sécurise la délivrance.</div>","frequence":0},{"id":"324-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les risques inhérents à une automédication","contenu":"<p>L'automédication, même de médicaments autorisés, expose à de nombreux <strong>risques</strong> :</p>\n      <table >\n        <thead><tr><th>Risque</th><th>Exemple</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Mésusage</span></td><td>Erreur de posologie, forme inadaptée (forme adulte chez l'enfant), durée trop courte ou arrêt brutal, non-respect des <span class=\"kw-ci\">CI</span>, médicament périmé</td></tr>\n          <tr><td><span class=\"kw-alerte\">Effets indésirables</span></td><td>Hémorragie digestive sous <span class=\"kw-ttt\">aspirine</span> ; somnolence sous <span class=\"kw-ttt\">antihistaminique H1</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Interactions médicamenteuses</span></td><td>Majoration du risque <span class=\"kw-etio\">hémorragique</span> (<span class=\"kw-ttt\">AINS</span> + anticoagulant) ; baisse d'absorption digestive avec un antiacide</td></tr>\n          <tr><td><span class=\"kw-alerte\">Risque iatrogène en grossesse</span></td><td><span class=\"kw-ttt\">Aspirine</span> au-delà de <span class=\"kw-chiffre\">24 SA</span> : toxicité cardiopulmonaire fœtale, insuffisance rénale sur oligohydramnios</td></tr>\n          <tr><td><span class=\"kw-alerte\">Pharmacodépendance / addiction</span></td><td>Antitussif à base de <span class=\"kw-ttt\">codéine</span> ; comportements addictifs ; dopage</td></tr>\n          <tr><td><span class=\"kw-alerte\">Retard de diagnostic</span></td><td>Urgence vitale masquée (<span class=\"kw-def\">SCA</span>, EP, pneumopathie, <span class=\"kw-def\">AVC</span>, urgence digestive) ; pathologie chronique non explorée</td></tr>\n          <tr><td><span class=\"kw-alerte\">Complication / accident</span></td><td>Complication d'une affection bénigne ; AVP et accident du travail (somnolence)</td></tr>\n        </tbody>\n      </table>\n      <p>La prévention passe par l'<strong>éducation du patient</strong>, structurée en 3 temps :</p>\n      <table >\n        <thead><tr><th>Avant l'achat</th><th>Avant la prise</th><th>Au cours du traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Conseil du pharmacien ; lire les informations de la boîte ; <strong>vigilance accrue</strong> : grossesse / allaitement, allergie, sujet âgé <span class=\"kw-chiffre\">&gt; 75 ans</span>, enfant <span class=\"kw-chiffre\">&lt; 12 ans</span>, ALD</td>\n            <td>Lire la notice ; vérifier la <strong>date de péremption</strong> ; conserver médicament + notice ; ne pas laisser à la portée des enfants</td>\n            <td>Prévenir les <span class=\"kw-alerte\">interactions</span> ; respecter posologie, intervalle et durée ; consulter si persistance ou aggravation ; signaler tout événement indésirable</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le risque le plus grave de l'automédication n'est pas l'effet indésirable direct, mais le <span class=\"kw-alerte\">retard de diagnostic d'une urgence vitale</span> dont le symptôme a été « éteint » par un médicament pris seul.</div>","frequence":0},{"id":"324-20","rang":"B","rubrique":"Définition","titre":"Connaître la définition de la « médecine personnalisée » (ou médecine de précision) et de la « médecine centrée sur la personne »","contenu":"<p>Ces deux notions partagent une même idée — <strong>adapter la prise en charge à l'individu</strong> — mais sous deux angles distincts :</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Ce que les fiches sources permettent d'en dire</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Médecine centrée sur la personne</span></td><td>Approche où la décision intègre les <strong>attentes, besoins, croyances et valeurs</strong> propres du patient ; le patient devient <strong>acteur</strong> de sa prise en charge (à rapprocher de la <span class=\"kw-def\">décision partagée</span> : pour une même pathologie, les objectifs peuvent légitimement différer d'un patient à l'autre)</td></tr>\n          <tr><td><span class=\"kw-def\">Médecine personnalisée</span> (ou médecine de précision)</td><td>Non définie formellement dans les fiches sources ; à rattacher à l'évaluation du <strong>terrain</strong> (génétique, état physiologique) qui module la prescription</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>À compléter.</strong> Les définitions formelles de la « médecine personnalisée / médecine de précision » et de la « médecine centrée sur la personne » ne figurent pas explicitement dans les fiches sources du dossier <code>324-education-therapeutique/</code>. Kevin enrichira ce paragraphe (Collège de thérapeutique, recherche ciblée).</div>\n      <!-- TODO Kevin : définitions formelles médecine personnalisée / de précision / centrée sur la personne -->","frequence":0},{"id":"324-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes pour « personnaliser » la prise en charge médicale","contenu":"<p>Le médecin dispose d'une <strong>liberté de prescription</strong>, encadrée par un <strong>contrat tacite</strong> avec le patient et l'engagement de sa responsabilité. Toute décision thérapeutique doit être <strong>personnalisée</strong> : évaluer le rapport <span class=\"kw-def\">bénéfices/risques</span> de la prescription — ou de la non-prescription — et tenir compte des attentes, besoins et croyances du patient.</p>\n      <p>Personnaliser une prise en charge suppose de connaître <strong>4 éléments pour traiter</strong> :</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Patient et maladie</strong></td><td>Maladie, état physiologique et psychologique</td></tr>\n          <tr><td><strong>Mode de vie et entourage</strong></td><td>Attentes et besoins du patient</td></tr>\n          <tr><td><strong>Traitements possibles</strong></td><td>Balance <span class=\"kw-def\">bénéfices / risques</span></td></tr>\n          <tr><td><strong>Éthique médicale</strong></td><td>Respect de l'autonomie et de la qualité de vie, dans une dimension empathique</td></tr>\n        </tbody>\n      </table>\n      <p>La décision thérapeutique peut suivre <strong>3 modèles</strong> :</p>\n      <table >\n        <thead><tr><th>Modèle</th><th>Échange d'information</th><th>Délibération &amp; décision</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Paternaliste</span></td><td>Unidirectionnel, descendant (médecin → patient), information minimale</td><td>Médecin seul</td></tr>\n          <tr><td><span class=\"kw-def\">Décision partagée</span></td><td>Bidirectionnel : contenu médical <strong>et</strong> valeurs du patient, information complète</td><td>Médecin <strong>et</strong> patient — <strong>modèle actuellement privilégié</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Informatif</span> (patient autonome)</td><td>Unidirectionnel, information complète</td><td>Patient seul (± entourage)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le modèle de <strong>décision partagée</strong> est privilégié : prendre en compte les attentes et besoins du patient améliore à la fois l'<span class=\"kw-def\">observance</span> et la satisfaction. Pour une même pathologie, les objectifs thérapeutiques peuvent légitimement différer d'un patient à l'autre.</div>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"42f82fa26fe8","n":324,"o":"324-1","u":"Définition","t":"Connaître la définition de l’éducation thérapeutique du patient et de ses principales étapes","q":"Quel est l'objectif principal de l'éducation thérapeutique du patient (ETP) ?","a":"<p>L'objectif principal de l'ETP est de développer les <strong>connaissances et compétences</strong> du patient pour gagner en <strong>autonomie</strong> et améliorer sa <strong>qualité de vie</strong>, en le transformant en acteur de sa prise en charge.</p>"},{"i":"533a921db819","n":324,"o":"324-1","u":"Définition","t":"Connaître la définition de l’éducation thérapeutique du patient et de ses principales étapes","q":"Quelle est la quatrième et dernière étape de la démarche d'éducation thérapeutique du patient (ETP) ?","a":"<p>La quatrième et dernière étape de la démarche ETP est l'<strong>évaluation individuelle</strong>. Cette étape permet de faire le point sur ce que le patient a compris et sait faire, et de proposer, si nécessaire, un nouvel ETP selon les résultats.</p>"},{"i":"578ae5a3db7c","n":324,"o":"324-1","u":"Définition","t":"Connaître la définition de l’éducation thérapeutique du patient et de ses principales étapes","q":"Quelle est la première étape de la démarche d'éducation thérapeutique du patient (ETP) ?","a":"<p>La première étape de la démarche ETP est le <strong>diagnostic éducatif</strong>. Elle consiste à identifier les <strong>connaissances, besoins et attentes</strong> du patient, et à formuler avec lui les compétences à acquérir.</p>"},{"i":"c1c99eb9b5cc","n":324,"o":"324-1","u":"Définition","t":"Connaître la définition de l’éducation thérapeutique du patient et de ses principales étapes","q":"Quelle est la deuxième étape de la démarche d'éducation thérapeutique du patient (ETP) ?","a":"<p>La deuxième étape de la démarche ETP est l'élaboration du <strong>programme personnalisé d'ETP</strong>. Il s'agit de définir les <strong>priorités d'apprentissage</strong> en fonction du projet du patient.</p>"},{"i":"c3c96e7d3ac8","n":324,"o":"324-1","u":"Définition","t":"Connaître la définition de l’éducation thérapeutique du patient et de ses principales étapes","q":"Selon l'OMS, quelle est la définition de l'éducation thérapeutique du patient (ETP) ?","a":"<p>L'éducation thérapeutique du patient (ETP) est « un ensemble de pratiques visant à permettre au patient l'acquisition de <strong>compétences</strong>, afin de pouvoir prendre en charge de manière active sa maladie, ses soins et sa surveillance, en <strong>partenariat avec ses soignants</strong> » (OMS, 1998).</p>"},{"i":"dd41cef592d6","n":324,"o":"324-1","u":"Définition","t":"Connaître la définition de l’éducation thérapeutique du patient et de ses principales étapes","q":"Quelle est la troisième étape de la démarche d'éducation thérapeutique du patient (ETP) ?","a":"<p>La troisième étape de la démarche ETP est la <strong>planification et la mise en œuvre des séances</strong>. Celles-ci peuvent être des séances individuelles et/ou collectives.</p>"},{"i":"1fce40dcecc6","n":324,"o":"324-10","u":"Prise en charge","t":"Connaître les facteurs améliorant l’observance médicamenteuse et non médicamenteuse","q":"Comment l'information et l'éducation thérapeutique du patient contribuent-elles à améliorer l'observance ?","a":"<p>L'information et l'éducation thérapeutique contribuent à améliorer l'observance en faisant comprendre au patient :</p><ul><li>Les <strong>bénéfices attendus</strong> du traitement.</li><li>Les <strong>modalités de prise</strong>.</li><li>Les <strong>risques d'effets indésirables</strong> et la surveillance nécessaire.</li></ul>"},{"i":"c811b4452d29","n":324,"o":"324-10","u":"Prise en charge","t":"Connaître les facteurs améliorant l’observance médicamenteuse et non médicamenteuse","q":"Quels sont les facteurs liés au traitement permettant d'améliorer l'observance médicamenteuse ?","a":"<p>Les facteurs liés au traitement qui améliorent l'observance sont :</p><ul><li>La <strong>simplification du schéma</strong> : administration simple, nombre de prises réduit, traitement de courte durée si possible.</li><li>L'<strong>optimisation du traitement</strong> : choix d'un traitement bien toléré et efficace, permettant un bon contrôle de la maladie.</li></ul>"},{"i":"cb4810e1bc8b","n":324,"o":"324-10","u":"Prise en charge","t":"Connaître les facteurs améliorant l’observance médicamenteuse et non médicamenteuse","q":"Quels sont les leviers de la relation soignant-soigné qui améliorent l'observance thérapeutique ?","a":"<p>Les leviers de la relation soignant-soigné qui améliorent l'observance thérapeutique sont :</p><ul><li>L'<strong>alliance thérapeutique</strong>.</li><li>La <strong>décision partagée</strong> avec le patient.</li><li>L'adoption d'une <strong>attitude de non-jugement</strong>.</li><li>L'<strong>accompagnement du patient</strong> pour repérer et prendre en charge ses problématiques psycho-sociales.</li></ul>"},{"i":"0e1c22fdea30","n":324,"o":"324-11","u":"Diagnostic positif","t":"Savoir qu’un même patient peut présenter différents comportements de non observance","q":"Quelle approche doit-on adopter pour évaluer la non-observance d'un traitement chez un patient ?","a":"<p>L'évaluation de la non-observance doit être <strong>nuancée et répétée</strong>, afin de prendre en compte sa nature souvent partielle et variable dans le temps.</p>"},{"i":"19984eb32c0e","n":324,"o":"324-11","u":"Diagnostic positif","t":"Savoir qu’un même patient peut présenter différents comportements de non observance","q":"Quelles sont les différentes formes de non-observance qu'un patient peut présenter ?","a":"<ul><li><strong>Non-retrait</strong> : le médicament n'est pas retiré en pharmacie.</li><li><strong>Non-consommation</strong> : le médicament est acheté mais non consommé.</li><li><strong>Sous-dosage</strong> : prises de doses plus faibles que prescrites (rarement plus fortes).</li><li><strong>Irrégularité</strong> : non-respect des horaires ou du nombre de prises.</li><li><strong>Arrêt prématuré</strong> : non-respect de la durée du traitement.</li><li><strong>Prise injustifiée</strong> : prises non prescrites, éventuellement avec automédication associée.</li></ul>"},{"i":"c231df068b8c","n":324,"o":"324-11","u":"Diagnostic positif","t":"Savoir qu’un même patient peut présenter différents comportements de non observance","q":"Comment doit-on considérer le comportement de non-observance chez un patient, est-ce un phénomène uniforme ou variable ?","a":"<p>La non-observance n'est <strong>pas un comportement unique et binaire</strong> (« tout ou rien »). Un même patient peut présenter <strong>plusieurs formes</strong> de non-observance, et celles-ci peuvent <strong>varier dans le temps</strong>. Elle est le plus souvent partielle et variable.</p>"},{"i":"2467d74a54f3","n":324,"o":"324-14","u":"Définition","t":"Connaître la définition des différents types d’automédication","q":"Quelle est la définition de l'automédication selon l'OMS ?","a":"<p>L'automédication, selon l'OMS, désigne le traitement de certaines maladies par les patients eux-mêmes, grâce à des <strong>médicaments autorisés, accessibles sans ordonnance, sûrs et efficaces</strong>.</p>"},{"i":"7f39996ec254","n":324,"o":"324-14","u":"Définition","t":"Connaître la définition des différents types d’automédication","q":"Comment se définit l'automédication « sauvage » ?","a":"<p>L'automédication « sauvage » consiste, pour le patient, à prendre un médicament de sa propre initiative ou sur conseil d'un proche, souvent depuis sa pharmacie familiale, face à une <strong>situation aiguë</strong> qu'il connaît ou pense reconnaître.</p>"},{"i":"b543d4a92367","n":324,"o":"324-14","u":"Définition","t":"Connaître la définition des différents types d’automédication","q":"Qu'est-ce que l'automédication contrôlée ?","a":"<p>L'automédication contrôlée correspond à l'utilisation de <strong>médicaments dûment autorisés</strong> (médicament d'automédication) obtenue avec le <strong>conseil du pharmacien d'officine</strong>. Ces médicaments bénéficient d'une AMM spécifique délivrée par une commission ad hoc de l'ANSM.</p>"},{"i":"d53846e2b165","n":324,"o":"324-14","u":"Définition","t":"Connaître la définition des différents types d’automédication","q":"Dans quelles situations parle-t-on d'automédication non responsable ?","a":"<p>L'automédication est considérée comme non responsable dans plusieurs situations, notamment :<ul><li>la <strong>réutilisation de médicaments antérieurement prescrits</strong> (issus de la pharmacie familiale)</li><li>une <strong>longue durée</strong> de prise</li><li>une pratique <strong>non déclarée au médecin/pharmacien</strong></li><li>une utilisation <strong>inadaptée</strong></li><li>la prise de <strong>médicaments inconnus</strong> (provenant de l'entourage ou achetés sur Internet)</li><li>la prise de <strong>plusieurs médicaments simultanément</strong></li><li>l'utilisation <strong>pendant la grossesse ou chez l'enfant en bas âge</strong>.</li></ul></p>"},{"i":"f5efb772c239","n":324,"o":"324-14","u":"Définition","t":"Connaître la définition des différents types d’automédication","q":"Quels sont les critères d'une automédication responsable ?","a":"<p>Une automédication est dite responsable si elle concerne des <ul><li><strong>symptômes courants et bénins</strong></li><li>d'une <strong>courte durée</strong></li><li>utilisant des <strong>spécialités simples</strong> (un seul principe actif)</li><li>avec <strong>respect des exigences de sécurité</strong></li><li>impliquant une <strong>consultation médicale si persistance</strong> des symptômes</li><li>une <strong>information du médecin</strong>.</li></ul> Elle est souvent guidée par le <strong>conseil du pharmacien</strong> et l'<strong>éducation du patient</strong>.</p>"},{"i":"0b47c3432f29","n":324,"o":"324-16","u":"Définition","t":"Connaître les principaux médicaments concernés par l’automédication","q":"Quelle a été la modification importante concernant le paracétamol et certains AINS (ibuprofène, aspirine) depuis le 15 janvier 2020 ?","a":"<p>Depuis le <strong>15 janvier 2020</strong>, ces médicaments sont placement <strong>derrière le comptoir du pharmacien</strong>. Ils restent sans ordonnance mais ne sont plus en accès direct.</p>"},{"i":"4ae30836e319","n":324,"o":"324-16","u":"Définition","t":"Connaître les principaux médicaments concernés par l’automédication","q":"Quelles sont les caractéristiques des médicaments de \"médication officinale\" ?","a":"<ul><li>Ils sont délivrés sur demande au pharmacien.</li><li>Ils représentent la majorité des médicaments d'automédication.</li><li>Ils peuvent être remboursables ou non par la Sécurité sociale.</li></ul>"},{"i":"af68b28cfe71","n":324,"o":"324-16","u":"Définition","t":"Connaître les principaux médicaments concernés par l’automédication","q":"Quels types de médicaments sont non éligibles à l'automédication ?","a":"<ul><li>Ceux comportant des <strong>contre-indications majeures</strong> ou des risques d'<strong>interactions</strong>.</li><li>Les médicaments destinés à la <strong>population pédiatrique</strong>.</li></ul>"},{"i":"b584cb09ae1f","n":324,"o":"324-16","u":"Définition","t":"Connaître les principaux médicaments concernés par l’automédication","q":"Quelles sont les caractéristiques des médicaments en \"accès direct\" (libre accès/OTC) ?","a":"<ul><li>Ils sont placés <strong>devant le comptoir</strong> du pharmacien, le patient peut se servir seul.</li><li>Ils sont au nombre d'environ 600 et leur liste est fixée par l'<strong>ANSM</strong>.</li><li>Ils sont <strong>non remboursables</strong>.</li><li>Ils se répartissent en 3 sous-catégories : allopathiques, homéopathiques, et à base de plantes.</li></ul>"},{"i":"ba2697fab6dc","n":324,"o":"324-16","u":"Définition","t":"Connaître les principaux médicaments concernés par l’automédication","q":"Quelles sont les deux grandes catégories de médicaments concernés par l'automédication ?","a":"<p>Les deux grandes catégories sont les médicaments de <strong>médication officinale</strong> et les médicaments en <strong>accès direct</strong> (également appelés \"libre accès\" ou OTC).</p>"},{"i":"dbf1ff237c2b","n":324,"o":"324-16","u":"Définition","t":"Connaître les principaux médicaments concernés par l’automédication","q":"Quelles sont les conditions fixées par l'ANSM pour qu'un médicament soit éligible à l'automédication ?","a":"<ul><li>Un <strong>rapport bénéfice/risque éminemment favorable</strong>.</li><li>Une pathologie ciblée courante et <strong>bénigne</strong>.</li><li>Un conditionnement, une posologie et une notice adaptés pour une <strong>courte durée</strong> d'utilisation.</li><li>Le patient doit être averti de la nécessité de consulter en cas de <strong>persistance des symptômes</strong>.</li></ul>"},{"i":"5dc603a170a1","n":324,"o":"324-18","u":"Etiologie","t":"Connaître les acteurs de l’automédication et les facteurs influençant leurs choix","q":"Concernant l'automédication, quels sont les trois acteurs principaux mis en jeu ?","a":"<p>Les trois acteurs principaux de l'automédication sont :</p><ul><li>Le <strong>patient</strong> (et son entourage).</li><li>Le <strong>pharmacien d'officine</strong>.</li><li>Le <strong>médecin</strong>.</li></ul>"},{"i":"aa8ef23e9da1","n":324,"o":"324-18","u":"Etiologie","t":"Connaître les acteurs de l’automédication et les facteurs influençant leurs choix","q":"Quel est le rôle spécifique du médecin face à l'automédication chez ses patients ?","a":"<p>Le rôle du médecin face à l'automédication inclut :</p><ul><li>Identifier l'automédication par un <strong>interrogatoire systématique</strong>.</li><li>Connaître et dépister les <strong>interactions médicamenteuses</strong>.</li><li>Rechercher une étiologie <strong>iatrogène</strong> devant tout nouveau symptôme.</li><li>Informer et éduquer le patient.</li><li>Déclarer tout effet indésirable (EI) grave ou inattendu au <strong>Centre Régional de Pharmacovigilance</strong>.</li></ul>"},{"i":"ad1e5f7c3a49","n":324,"o":"324-18","u":"Etiologie","t":"Connaître les acteurs de l’automédication et les facteurs influençant leurs choix","q":"Quel est le rôle spécifique du pharmacien d'officine dans le cadre de l'automédication ?","a":"<p>Le rôle du pharmacien d'officine dans l'automédication est de :</p><ul><li>Fournir un <strong>conseil et une information claire et adaptée</strong>.</li><li>Expliquer les <strong>posologies et modalités d'utilisation</strong>.</li><li>Donner des <strong>consignes de vigilance</strong> (notamment pour les enfants et sujets âgés).</li><li>Rechercher systématiquement une <strong>grossesse</strong>.</li><li>Rechercher les <strong>contre-indications et précautions d'emploi</strong> du médicament.</li></ul>"},{"i":"d9c6114c8be0","n":324,"o":"324-18","u":"Etiologie","t":"Connaître les acteurs de l’automédication et les facteurs influençant leurs choix","q":"Quels sont les facteurs principaux qui peuvent influencer le choix d'un individu de recourir à l'automédication ?","a":"<p>Les facteurs influençant le recours à l'automédication sont :</p><ul><li>Le <strong>profil socio-démographique</strong> (plus fréquent chez les <strong>femmes</strong>, les <strong>âges actifs</strong> et les personnes avec un <strong>niveau social élevé</strong>).</li><li>Le <strong>conseil de l'entourage</strong>.</li><li>L'<strong>accès facilité</strong> aux médicaments (libre-accès en officine, achat sur Internet).</li><li>Une <strong>situation aiguë connue ou pensée reconnue</strong>.</li><li>Le <strong>contenu de la pharmacie familiale</strong>.</li></ul>"},{"i":"42abef134be4","n":324,"o":"324-19","u":"Prise en charge","t":"Connaître les risques inhérents à une automédication","q":"Donnez des exemples de risques de mésusage en automédication.","a":"<p>Le mésusage en automédication peut se manifester par :</p><ul><li>Une <strong>erreur de posologie</strong>.</li><li>L'utilisation d'une <strong>forme inadaptée</strong> (ex: adulte chez l'enfant).</li><li>Une <strong>durée de traitement trop courte</strong> ou un arrêt brutal.</li><li>Le <strong>non-respect des contre-indications</strong>.</li><li>L'utilisation d'un <strong>médicament périmé</strong>.</li></ul>"},{"i":"7c892360ed63","n":324,"o":"324-19","u":"Prise en charge","t":"Connaître les risques inhérents à une automédication","q":"Quels sont les différents types de risques liés à l'automédication, même avec des médicaments autorisés ?","a":"<p>L'automédication expose à plusieurs catégories de risques :</p><ul><li>Le <strong>mésusage</strong>.</li><li>Les <strong>effets indésirables</strong>.</li><li>Les <strong>interactions médicamenteuses</strong>.</li><li>Le <strong>risque iatrogène</strong>, notamment pendant la grossesse.</li><li>La <strong>pharmacodépendance</strong> ou l'addiction.</li><li>Le <strong>retard de diagnostic</strong>.</li><li>Les <strong>complications</strong> ou accidents.</li></ul>"},{"i":"946a32947b2a","n":324,"o":"324-19","u":"Prise en charge","t":"Connaître les risques inhérents à une automédication","q":"Comment prévenir les risques liés à l'automédication en éduquant le patient avant l'achat ?","a":"<p>Avant l'achat en automédication, la prévention passe par :</p><ul><li>Le <strong>conseil du pharmacien</strong>.</li><li>La lecture des <strong>informations de la boîte</strong>.</li><li>Une <strong>vigilance accrue</strong> chez les populations à risque : la femme enceinte ou allaitante, les sujets allergiques, les sujets âgés de <strong>plus de 75 ans</strong>, les enfants de <strong>moins de 12 ans</strong> et les patients atteints d'ALD.</li></ul>"},{"i":"b15c44e0b1d4","n":324,"o":"324-19","u":"Prise en charge","t":"Connaître les risques inhérents à une automédication","q":"Quels conseils donner au patient pour la prise et le suivi d'un traitement en automédication afin de limiter les risques ?","a":"<p>Pour la prise et le suivi d'un traitement en automédication, le patient doit :</p><ul><li><strong>Lire la notice</strong> et vérifier la <strong>date de péremption</strong>.</li><li>Conserver le médicament et la notice, et <strong>ne pas laisser à la portée des enfants</strong>.</li><li>Prévenir les interactions, respecter la <strong>posologie</strong>, l'<strong>intervalle</strong> et la <strong>durée</strong>.</li><li><strong>Consulter un professionnel de santé</strong> si la persistance ou l'aggravation des symptômes survient.</li><li><strong>Signaler tout événement indésirable</strong>.</li></ul>"},{"i":"fd21afe625a0","n":324,"o":"324-19","u":"Prise en charge","t":"Connaître les risques inhérents à une automédication","q":"Quel est le risque le plus grave de l'automédication, et pourquoi ?","a":"<p>Le risque le plus grave de l'automédication n'est pas un effet indésirable direct, mais le <strong>retard de diagnostic d'une urgence vitale</strong>.</p><p>Cela se produit lorsque le symptôme d'une urgence (comme un SCA, une EP, un AVC, ou une urgence digestive) est masqué ou \"éteint\" par un médicament pris seul, retardant ainsi la prise en charge médicale nécessaire.</p>"},{"i":"032a7af1fd11","n":324,"o":"324-6","u":"Définition","t":"Connaître la définition des notions d’observance, de concordance et d’alliance en thérapeutique","q":"Quelle est la définition de l'observance thérapeutique ?","a":"<p>L'observance thérapeutique est le niveau auquel le comportement du patient coïncide avec les <strong>prescriptions médicamenteuses</strong> et les soins au sens large (consultations, explorations, surveillance). Il s'agit d'une <strong>donnée factuelle</strong>, englobant la prise médicamenteuse, le suivi des règles hygiéno-diététiques et le suivi médical.</p>"},{"i":"0efd622f65e6","n":324,"o":"324-6","u":"Définition","t":"Connaître la définition des notions d’observance, de concordance et d’alliance en thérapeutique","q":"Qu'est-ce que la concordance thérapeutique ?","a":"<p>La concordance thérapeutique est le niveau d'<strong>accord entre les prescriptions médicales</strong> et le comportement du patient en réponse à ces recommandations. Elle implique une entente mutuelle sur le plan de traitement.</p>"},{"i":"4c8557d56cc5","n":324,"o":"324-6","u":"Définition","t":"Connaître la définition des notions d’observance, de concordance et d’alliance en thérapeutique","q":"Comment distinguer l'adhésion de l'observance dans le contexte thérapeutique ?","a":"<p>L'<strong>adhésion</strong> fait référence à la participation active du patient à sa prise en charge, c'est une dimension de l'observance. L'<strong>observance</strong> est une notion plus large et factuelle qui évalue si le comportement du patient coïncide avec les prescriptions, incluant donc l'adhésion ainsi que la maintenance du traitement.</p>"},{"i":"da45471f20fa","n":324,"o":"324-6","u":"Définition","t":"Connaître la définition des notions d’observance, de concordance et d’alliance en thérapeutique","q":"Définissez l'alliance thérapeutique et son lien avec l'observance.","a":"<p>L'alliance thérapeutique est une <strong>collaboration</strong> entre le patient et le soignant menant à des prescriptions concertées. Elle inclut l'adhésion au traitement. Contrairement à l'observance qui est une mesure factuelle, l'alliance thérapeutique est une <strong>relation</strong> qui aboutit à des décisions partagées, favorisant indirectement une meilleure observance.</p>"},{"i":"111581be4d99","n":324,"o":"324-7","u":"Epidémiologie","t":"Connaître les principaux éléments épidémiologiques de la non observance et ses conséquences potentielles en termes de santé publique","q":"Quel seuil définit une mauvaise adhésion thérapeutique et quelles sont les conséquences individuelles et collectives de la non-observance ?","a":"<ul><li>Une mauvaise adhésion est définie par moins de <strong>80 % des prises</strong>.</li><li>Au niveau individuel, elle expose à l'<strong>échec thérapeutique</strong> et aux <strong>risques thérapeutiques</strong> (liés à une mauvaise utilisation ou à l'absence d'effet attendu).</li><li>À l'échelle de la santé publique, elle explique une partie de la différence entre les conclusions des essais cliniques et les résultats observés en pratique réelle.</li></ul>"},{"i":"31b9a869b8cb","n":324,"o":"324-7","u":"Epidémiologie","t":"Connaître les principaux éléments épidémiologiques de la non observance et ses conséquences potentielles en termes de santé publique","q":"Quelle est la prévalence de la non-observance thérapeutique dans les maladies chroniques et dans les populations spécifiques comme les adolescents ou la prévention primaire ?","a":"<ul><li>La non-observance concerne en moyenne <strong>~50 % des patients</strong> dans les maladies chroniques, avec une fourchette de <strong>20 à 70 %</strong>.</li><li>Elle est d'autant plus fréquente que la maladie est <strong>peu ou pas symptomatique</strong>.</li><li>En prévention primaire, un arrêt fréquent du traitement est observé au bout de <strong>2 ans</strong>.</li><li>Elle atteint environ <strong>40 %</strong> chez les adolescents.</li></ul>"},{"i":"953b5e017111","n":324,"o":"324-7","u":"Epidémiologie","t":"Connaître les principaux éléments épidémiologiques de la non observance et ses conséquences potentielles en termes de santé publique","q":"La non-observance thérapeutique des traitements des pathologies chroniques représente-t-elle un problème de santé publique ?","a":"<p>Oui, la non-observance thérapeutique constitue un problème <strong>majeur de santé publique</strong>, touchant toutes les pathologies chroniques.</p>"},{"i":"f6d4f13804c7","n":324,"o":"324-7","u":"Epidémiologie","t":"Connaître les principaux éléments épidémiologiques de la non observance et ses conséquences potentielles en termes de santé publique","q":"Quel piège clinique typique est associé à la non-observance thérapeutique lors d'un échec ou d'un échappement thérapeutique ?","a":"<p>Devant tout échec ou échappement thérapeutique, le piège classique est de ne pas évoquer la non-observance en premier lieu. Il faut <strong>toujours l'envisager avant d'ajouter un autre traitement</strong>, afin d'éviter une <strong>escalade thérapeutique injustifiée</strong>.</p>"}]};